	public static boolean verifyIdentify(String identifyHeader) {
		try {
			// 1. 解码
			byte[] decodedBytes = Base64.getDecoder().decode(identifyHeader);
			String decoded = new String(decodedBytes, StandardCharsets.UTF_8);

			// 2. 解析
			String[] parts = decoded.split(":");
			if (parts.length != 3) return false;
			String receivedSign = parts[0];
			String appKey = parts[1];
			String time = parts[2];

			/*// 3. 验证时间戳
			long currentTime = System.currentTimeMillis();
			if (Math.abs(currentTime - Long.parseLong(time)) > 300_000) {
				return false;
			}*/

			// 4. 获取 appSecret
			String appSecret = "eLkYS5bb1SfPeIh6nx10"; // 需实现

			// 5. 重新生成并比对签名
			String serverSign = sign(appKey, appSecret, time);
			return MessageDigest.isEqual(
					serverSign.getBytes(StandardCharsets.UTF_8),
					receivedSign.getBytes(StandardCharsets.UTF_8)
			);
		} catch (Exception e) {
			return false;
		}
	}

